				&QueryString;

declare @queryWhereClause nvarchar(4000), @queryFormClause nvarchar(4000)
select @queryWhereClause = 'b.status <> ''*'''
IF @ma_vt <> '' SET @queryWhereClause += ' and a.ma_vt like ''' + REPLACE(RTRIM(@ma_vt), '''', '''''') + '%'''
IF @ma_kh <> '' SET @queryWhereClause += ' and b.ma_kh like ''' + REPLACE(RTRIM(@ma_kh), '''', '''''') + '%'''
if @loai = '1' begin
	select @queryWhereClause += ' and b.ma_gd in (''8'',''9'') and b.status in (''4'', ''2'',''5'')'
end
if @loai = '2' begin
	select @queryWhereClause += ' and b.ma_gd in (''1'') and b.status in (''4'', ''2'',''5'') and a.stt_rec_dh3 <> '''''
end

&FilterInitialize;&FilterQuery;

select top 0 * into #d64 from d64$000000
set @q = '
insert into #d64
	select a.* 
		from d64$%Partition a 
			join m64$%Partition b on a.stt_rec = b.stt_rec
			left join dmvt c on a.ma_vt = c.ma_vt
		where %['+ @queryWhereClause+']%'
exec FastBusiness$Partition$Execute @q, NULL, 'a.ngay_ct',@tu_ngay,@den_ngay, @@userID, @@admin

select @q =  'select ' + @@textExternal + ' from #d64 a left join dmvt b on a.ma_vt = b.ma_vt order by a.ngay_ct, a.stt_rec, a.line_nbr'
exec(@q)







