function init$GridQuery$(g) {
	var a = g._queryFilterString.split(String.fromCharCode(253));
	g._alterTitle = [null, [['%d1', formatDateView(a[3]), true], ['%d2', formatDateView(a[4]), true]]];
	g._hiddenFields = [];
}
